package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Every problem in the file is collected and reported together in one {@link ConfigException}. A value that is
 * present but wrong is never replaced by a default: the relay must not run with settings nobody wrote.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();
        rejectUnknownKeys(properties, problems);
        URI upstream = upstream(properties, problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", problems);
        if (!problems.isEmpty()) {
            throw new ConfigException(describe(file, problems));
        }
        return new ServiceConfig(
                upstream,
                apiToken,
                workerThreads,
                queueCapacity,
                retryAttempts,
                requestTimeout,
                metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("cannot read configuration file " + file + ": file not found");
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file + ": " + e.getMessage());
        }
        return properties;
    }

    private static String describe(Path file, List<String> problems) {
        StringBuilder message = new StringBuilder("invalid configuration in " + file + ":");
        for (String problem : problems) {
            message.append("\n  - ").append(problem);
        }
        return message.toString();
    }

    private static void rejectUnknownKeys(Properties properties, List<String> problems) {
        properties.stringPropertyNames().stream()
                .sorted()
                .filter(key -> !KNOWN_KEYS.contains(key))
                .forEach(key -> problems.add("unknown key \"" + key + "\""));
    }

    private static URI upstream(Properties properties, List<String> problems) {
        String raw = required(properties, "upstream.url", problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme)) && uri.getHost() != null) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add("upstream.url must be an http or https URL, got \"" + raw + "\"");
        return null;
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String text = raw.trim();
        try {
            int value = Integer.parseInt(text);
            if (value >= minimum) {
                return value;
            }
            problems.add(key + " must be at least " + minimum + ", got \"" + text + "\"");
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number of at least " + minimum + ", got \"" + text + "\"");
        }
        // Never used: load() throws because a problem was recorded.
        return defaultValue;
    }

    private static Duration duration(Properties properties, List<String> problems) {
        String raw = properties.getProperty("request.timeout");
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        String text = raw.trim();
        Duration parsed = parseDuration(text);
        if (parsed != null) {
            return parsed;
        }
        problems.add("request.timeout must be a whole number followed by ms, s or m, such as 500ms, 30s or 2m, got \""
                + text + "\"");
        // Never used: load() throws because a problem was recorded.
        return DEFAULT_REQUEST_TIMEOUT;
    }

    private static Duration parseDuration(String text) {
        Matcher matcher = DURATION.matcher(text);
        if (!matcher.matches()) {
            return null;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            return null;
        }
    }

    private static boolean bool(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String text = raw.trim();
        if (text.equalsIgnoreCase("true")) {
            return true;
        }
        if (text.equalsIgnoreCase("false")) {
            return false;
        }
        problems.add(key + " must be true or false, got \"" + text + "\"");
        // Never used: load() throws because a problem was recorded.
        return false;
    }
}

